interface.definition:
a!localVariables(
  local!audithistory: #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3442778"(requestId: ri!nomination.nominationId, ).data,
  local!isMarkedCompleteDate: index(
    index(local!audithistory,"createdOn",{}),
    wherecontains(
      tostring(#"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14227992"),
      touniformstring(local!audithistory.action)
    ),
    {}
  ),
  local!isrequestAfterV5Deployment: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    true,
    if(
      todatetime(ri!nomination.createdOn) > #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14165460",
      true,
      if(
        or(
          a!isNullOrEmpty(local!isMarkedCompleteDate),
          and(
            a!isNotNullOrEmpty(local!isMarkedCompleteDate),
            todatetime(local!isMarkedCompleteDate) > #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14165460"
          )
        ),
        true,
        false()
      )
    ),

  ),
  {
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_textField"(
                label: "Candidate Name",
                value: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3928917"(
                  firstName: ri!nomination.firstName,
                  middleName: ri!nomination.middleName,
                  lastName: ri!nomination.lastName
                ),
                readOnly: true
              ),
              #"SYSTEM_SYSRULES_textField"(
                label: "Anticipated Start Date",
                readOnly: true,
                value: ri!nomination.anticipatedStartDate,
                showWhen: toboolean(local!isrequestAfterV5Deployment) = true
              ),
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_textField"(
                label: "Position Type",
                value: displayvalue(
                  tointeger(ri!candidateDetails.positionType),
                  index(ri!refData, "refId", {}),
                  index(ri!refData, "description",{}),
                  null
                ),
                readOnly: true
              ),
              #"SYSTEM_SYSRULES_textField"(
                label: "Anticipated End Date",
                readOnly: true,
                value: ri!nomination.anticipatedEndDate,
                showWhen: toboolean(local!isrequestAfterV5Deployment) = true
              ),
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_textField"(
                label: "Position Sub Type",
                value: displayvalue(
                  tointeger(ri!candidateDetails.subPosition),
                  index(ri!subPositionTypes, "subPositionId", {}),
                  index(ri!subPositionTypes, "subPosition",{}),
                  null
                ),
                readOnly: true
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_textField"(
                label: "Candidate Projected Start Date",
                instructions: "Provided by candidate",
                value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                  value: ri!candidateDetails.candidateProjectedStartDate,
                  isBoolean: false
                ),
                readOnly: true
              )
            }
          )
        }
      ),
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: ri!candidateDetails.congratsWelcomeMessage,
              style: "STRONG"
            )
          )
        },
        showWhen: true,
        style: "INFO",
        padding: "STANDARD",
        marginBelow: "STANDARD",
        showShadow: true
      )
    },
    marginBelow: "STANDARD"
  ),
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      #"SYSTEM_SYSRULES_checkboxField"(
        label: "Acknowledgement",
        choiceLabels: {"I formally accept the DPP position and have discussed the start date with my BU leadership"},
        choiceValues: {true},
        value: ri!candidateDetails.isAcceptanceAck,
        disabled: true
      ),
      #"SYSTEM_SYSRULES_paragraphField"(
        label: "Additional Notes",
        instructions: "Provided by candidate",
        value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
          value: ri!candidateDetails.candidateFormalNotificationNote,
          isBoolean: false
        ),
        readOnly: true
      )
    },
    marginBelow: "STANDARD"
  )
}
)
